######### the-rise-of-model-driven-data-engineer
{
 "name": "DAS data contract (full YAML, verbatim)",
 "kind": "yaml-file",
 "detail": "# Declarative approach: Data contract\nversion: \"1.0\"\nvalid_from: \"2025-01-01\"\n\nendpoints:\n  source:\n    provider: kafka\n    entity: user_events\n\nschema:\n  primary_keys:\n    - user_id\n    - event_id\n\n  columns:\n    - source_path: payload.userId\n      target_name: user_id\n      type: INTEGER\n      mode: REQUIRED\n      description: \"User account identifier\"\n\n    - source_path: eventType\n      target_name: event_type\n      type: STRING\n      mode: REQUIRED\n      description: \"Event type (USER_CREATED, USER_UPDATED, etc.)\"\n\n    - source_path: timestamp\n      target_name: event_ts\n      type: TIMESTAMP_MILLIS\n      mode: REQUIRED\n      description: \"Event timestamp in milliseconds\""
}
---
{
 "name": "version",
 "kind": "yaml-key (contract, top level)",
 "detail": "version: \"1.0\" \u2014 quoted string. Contract version."
}
---
{
 "name": "valid_from",
 "kind": "yaml-key (contract, top level)",
 "detail": "valid_from: \"2025-01-01\" \u2014 quoted ISO date. Implies contracts are time-versioned/effective-dated, supporting the post's point that contracts require 'thought about versioning, backward compatibility'."
}
---
{
 "name": "endpoints.source.provider",
 "kind": "yaml-key (contract)",
 "detail": "provider: kafka \u2014 unquoted. Names the source system type. Nested under endpoints: > source:. The 'endpoints' plural + named 'source' key implies other endpoint roles are possible."
}
---
{
 "name": "endpoints.source.entity",
 "kind": "yaml-key (contract)",
 "detail": "entity: user_events \u2014 unquoted. The source-side object/topic name."
}
---
{
 "name": "schema.primary_keys",
 "kind": "yaml-key (contract)",
 "detail": "A list of target-side column names: - user_id / - event_id. Composite keys supported. Note: event_id is listed as a primary key but is NOT declared in the columns list of the shown example."
}
---
{
 "name": "schema.columns[]",
 "kind": "yaml-key (contract)",
 "detail": "A list of column mappings, each with exactly five keys in this order: source_path, target_name, type, mode, description."
}
---
{
 "name": "source_path",
 "kind": "yaml-key (contract column)",
 "detail": "Dot-delimited path into the source payload, unquoted. Examples: payload.userId (nested), eventType (top level), timestamp (top level). This is the mechanism for 'extract nested JSON fields'."
}
---
{
 "name": "target_name",
 "kind": "yaml-key (contract column)",
 "detail": "Unquoted snake_case output column name. Examples: user_id, event_type, event_ts. Note the rename discipline: source camelCase (userId, eventType) becomes snake_case; 'timestamp' becomes 'event_ts'."
}
---
{
 "name": "type",
 "kind": "yaml-key (contract column)",
 "detail": "Unquoted, SCREAMING_CASE. Observed values: INTEGER, STRING, TIMESTAMP_MILLIS."
}
---
{
 "name": "mode",
 "kind": "yaml-key (contract column)",
 "detail": "Unquoted. Only observed value: REQUIRED. (BigQuery-style mode vocabulary; NULLABLE/REPEATED are not shown but implied by the naming convention.)"
}
---
{
 "name": "description",
 "kind": "yaml-key (contract column)",
 "detail": "Double-quoted free text. Used to carry enum vocabularies inline, e.g. \"Event type (USER_CREATED, USER_UPDATED, etc.)\"."
}
---
{
 "name": "Contract type vocabulary",
 "kind": "type-mapping",
 "detail": "INTEGER, STRING, TIMESTAMP_MILLIS \u2014 the only DAS contract types shown. TIMESTAMP_MILLIS is notable: precision is encoded in the type name, not a separate key."
}
---
{
 "name": "DMDL entity model (full YAML, verbatim)",
 "kind": "yaml-file",
 "detail": "# Declarative entity definition in DMDL\nentities:\n  - id: \"SUBSCRIPTION\"\n    name: \"SUBSCRIPTION\"\n    definition: \"A customer subscription\"\n    description: \"Represents an active or historical subscription to a service plan\"\n    attributes:\n      - id: \"SUBSCRIPTION_ID\"\n        name: \"SUBSCRIPTION_ID\"\n        definition: \"Unique subscription identifier\"\n        type: \"STRING\"\n        effective_timestamp: false\n\n      - id: \"ACQUISITION_TYPE\"\n        name: \"ACQUISITION_TYPE\"\n        definition: \"How the subscription was acquired\"\n        description: \"Origin channel: ORGANIC, CAMPAIGN, REFERRAL, TRIAL_CONVERSION\"\n        type: \"STRING\"\n        effective_timestamp: true\n\n      - id: \"STATUS\"\n        name: \"STATUS\"\n        definition: \"Current subscription status\"\n        description: \"Status derived from dates: ACTIVE, CANCELLED, EXPIRED\"\n        type: \"STRING\"\n        effective_timestamp: true\n\n      - id: \"SUBSCRIPTION_START_DATE\"\n        name: \"SUBSCRIPTION_START_DATE\"\n        definition: \"When subscription activated\"\n        type: \"START_TIMESTAMP\"\n\n      - id: \"SUBSCRIPTION_END_DATE\"\n        name: \"SUBSCRIPTION_END_DATE\"\n        definition: \"When subscription expires or was cancelled\"\n        type: \"END_TIMESTAMP\"\n\n      - id: \"MONTHLY_VALUE\"\n        name: \"MONTHLY_VALUE\"\n        definition: \"Monthly subscription value with currency\"\n        effective_timestamp: true\n        group:\n          - id: \"MONTHLY_VALUE\"\n            name: \"MONTHLY_VALUE\"\n            definition: \"The monetary amount\"\n            type: \"NUMBER\"\n          - id: \"MONTHLY_VALUE_CURRENCY\"\n            name: \"MONTHLY_VALUE_CURRENCY\"\n            definition: \"Currency code (USD, EUR, SEK)\"\n            type: \"UNIT\"\n\nrelationships:\n  - id: \"BELONGS_TO_ACCOUNT\"\n    name: \"BELONGS_TO_ACCOUNT\"\n    definition: \"Subscription belongs to an account\"\n    source_entity_id: \"SUBSCRIPTION\"\n    target_entity_id: \"ACCOUNT\"\n\n  - id: \"HAS_BASE_PLAN\"\n    name: \"HAS_BASE_PLAN\"\n    definition: \"Subscription is based on a plan\"\n    source_entity_id: \"SUBSCRIPTION\"\n    target_entity_id: \"BASE_PLAN\""
}
---
{
 "name": "DMDL",
 "kind": "language name",
 "detail": "\"Daana's Model Description Language (DMDL)\" \u2014 the named YAML dialect for declaring DAB entities and relationships."
}
---
{
 "name": "entities[] keys",
 "kind": "yaml-key (DMDL)",
 "detail": "id, name, definition, description, attributes. All string values are double-quoted. definition and description are BOTH present and distinct: definition is the short gloss (\"A customer subscription\"), description is the fuller prose (\"Represents an active or historical subscription to a service plan\")."
}
---
{
 "name": "attributes[] keys",
 "kind": "yaml-key (DMDL)",
 "detail": "id, name, definition, description (optional), type, effective_timestamp (optional), group (optional). description appears only on ACQUISITION_TYPE and STATUS; effective_timestamp is absent on SUBSCRIPTION_START_DATE and SUBSCRIPTION_END_DATE; type is absent on the grouped attribute MONTHLY_VALUE (type lives on the group members instead)."
}
---
{
 "name": "effective_timestamp",
 "kind": "yaml-key (DMDL attribute)",
 "detail": "Boolean, unquoted true/false. false on SUBSCRIPTION_ID (the key); true on ACQUISITION_TYPE, STATUS, MONTHLY_VALUE (the changing attributes). Omitted entirely on START_TIMESTAMP/END_TIMESTAMP-typed attributes. This is the flag that drives which attributes get slowly-changing-dimension treatment in the generated _HIST view."
}
---
{
 "name": "group",
 "kind": "yaml-key (DMDL attribute)",
 "detail": "A list of sub-attributes composing one logical attribute. Used for a value+unit pair: MONTHLY_VALUE (type NUMBER) + MONTHLY_VALUE_CURRENCY (type UNIT). Group members carry id, name, definition, type. The parent carries effective_timestamp; the members do not."
}
---
{
 "name": "DMDL type vocabulary",
 "kind": "type-mapping",
 "detail": "Double-quoted, SCREAMING_CASE: \"STRING\", \"NUMBER\", \"UNIT\", \"START_TIMESTAMP\", \"END_TIMESTAMP\". Note these are semantic, not physical: START_TIMESTAMP/END_TIMESTAMP declare validity-interval roles rather than a datatype, and UNIT declares a unit-of-measure companion to a NUMBER."
}
---
{
 "name": "relationships[] keys",
 "kind": "yaml-key (DMDL)",
 "detail": "id, name, definition, source_entity_id, target_entity_id. All double-quoted. No cardinality key appears in the example even though the prose says relationships need cardinalities. Relationship ids read as verb phrases: BELONGS_TO_ACCOUNT, HAS_BASE_PLAN."
}
---
{
 "name": "id == name convention",
 "kind": "naming-rule (DMDL)",
 "detail": "In every entity, attribute, group member and relationship shown, id and name hold the identical string. Both are SCREAMING_SNAKE_CASE and double-quoted."
}
---
{
 "name": "SCREAMING_SNAKE_CASE identifiers",
 "kind": "naming-rule (DMDL)",
 "detail": "Entities: SUBSCRIPTION, ACCOUNT, BASE_PLAN. Attributes: SUBSCRIPTION_ID, ACQUISITION_TYPE, STATUS, SUBSCRIPTION_START_DATE, SUBSCRIPTION_END_DATE, MONTHLY_VALUE, MONTHLY_VALUE_CURRENCY. Attributes are prefixed with the entity name (SUBSCRIPTION_ID, SUBSCRIPTION_START_DATE) except for generic ones (STATUS, ACQUISITION_TYPE). Contrast with DAS, which uses lowercase snake_case (user_id, event_type, event_ts)."
}
---
{
 "name": "SUBSCRIPTION_HIST / SUBSCRIPTION_LATEST",
 "kind": "generated sql object / view-naming rule",
 "detail": "\"create both SUBSCRIPTION_HIST (complete history) and SUBSCRIPTION_LATEST (current state) views\" \u2014 pattern is <ENTITY_ID>_HIST and <ENTITY_ID>_LATEST. Two views generated per DAB entity."
}
---
{
 "name": "historized and latest views (DAS)",
 "kind": "generated sql object",
 "detail": "The DAS unpacking generator also creates \"historized and latest views\" \u2014 the same HIST/LATEST duality exists one layer down, at staging."
}
---
{
 "name": "DAS / DAB / DAR",
 "kind": "layer names",
 "detail": "DAS = \"Data As System sees it\"; DAB = \"Data As Business sees it\"; DAR = \"Data As Requirements needs it\". Explicit mapping: \"they map to staging/core/marts in dbt terminology, or bronze/silver/gold in the medallion architecture.\""
}
---
{
 "name": "landing zone / staging",
 "kind": "DAS sub-stages",
 "detail": "\"DAS represents source systems without interpretation through two stages: landing zone and staging.\" Landing = raw as produced, often JSON strings, no schema enforcement. Staging = unpacked to tabular, faithful to source structure."
}
---
{
 "name": "Metric declaration shape (DAR)",
 "kind": "metric-shape",
 "detail": "Verbatim example: \"MRR equals sum of monthly_value for active subscriptions, dimensioned by plan_type and region, grain of monthly.\" Components named across the post: calculation logic, grain, dimensions. Note the DAR example references monthly_value / plan_type / region in lowercase snake_case, not the DMDL SCREAMING_CASE."
}
---
{
 "name": "Three DAR outputs from one declaration",
 "kind": "generation targets",
 "detail": "\"One declaration generates warehouse queries, drives API responses, and serves as documentation.\" Elsewhere: \"that declaration generates SQL for your warehouse, API responses for applications, and documentation for business users.\""
}
---
{
 "name": "data mappings declaration",
 "kind": "required-but-unspecified artifact",
 "detail": "\"From these declarations and a corresponding one for data mappings, systems generate transformation logic.\" A second DAB-layer input file, named but never shown."
}
---
{
 "name": "Enum vocabularies (carried in description text)",
 "kind": "value-vocabulary",
 "detail": "ACQUISITION_TYPE: \"Origin channel: ORGANIC, CAMPAIGN, REFERRAL, TRIAL_CONVERSION\". STATUS: \"Status derived from dates: ACTIVE, CANCELLED, EXPIRED\". MONTHLY_VALUE_CURRENCY: \"Currency code (USD, EUR, SEK)\". Event types: \"USER_CREATED, USER_UPDATED, etc.\". All carried as prose inside description \u2014 there is no enum/allowed_values key."
}
---
{
 "name": "customerID -> account_id",
 "kind": "worked example (layer isolation)",
 "detail": "\"When a source system renames customerID to account_id, only DAS changes - you update the contract mapping. DAB's Account entity remains unchanged... DAR consumers are unaffected.\""
}
---
{
 "name": "50-line YAML -> 100+ lines of SQL",
 "kind": "generation ratio",
 "detail": "Stated code-generation leverage for a single DAS contract."
}
---
{
 "name": "{{ ref() }}",
 "kind": "contrasted construct",
 "detail": "dbt's model reference syntax, cited as the example of \"improved imperative code, not declarative architecture\" \u2014 \"you write SQL - a SELECT statement referencing other models with {{ ref() }} syntax.\""
}
---
{
 "name": "Platform components required",
 "kind": "platform-component",
 "detail": "Three named: (1) model registries storing entity definitions as queryable metadata; (2) generation frameworks that translate models into correct transformations while leaving room for custom logic; (3) validation at the model level, before code generation."
}
---
{
 "name": "Tools named in the post",
 "kind": "tool",
 "detail": "Declarative/metrics: dbt semantic layer, Cube, Malloy, headless BI. Imperative/mature: dbt, Airflow, Fivetran. Source system in examples: Kafka (kafka-python KafkaConsumer, topic 'user_events', bootstrap_servers localhost:9092). NOT mentioned anywhere in the post: dlt, daana-cli, Unified Star Schema."
}
---
{
 "name": "Declarative vs imperative tradeoff table",
 "kind": "decision table",
 "detail": "Twelve rows, verbatim aspect names: Consistency, Quality, Documentation, Testing, AI Effectiveness, Productivity, Upfront Investment, Learning Curve, Edge Cases, Flexibility, Tooling Maturity, Debugging."
}
---
{
 "name": "Five cases where imperative wins",
 "kind": "decision rule",
 "detail": "One-off analyses; Genuinely novel algorithms; Performance-critical optimization; Early-stage exploration; Very small teams with simple needs (\"Three sources, ten entities, one data engineer\")."
}
---
######### why-we-built-daana
{
 "name": "entities:",
 "kind": "yaml-key",
 "detail": "Top-level YAML key holding a list of entity definitions. Verbatim first block:\nentities:\n  - id: \"CUSTOMER\"\n    name: \"CUSTOMER\"\n    definition: \"Customer who places orders\"\n    attributes:\n      - id: \"CUSTOMER_NAME\"\n        definition: \"Full name of the customer\"\n        type: \"STRING\"\n        effective_timestamp: true"
}
---
{
 "name": "id / name / definition / attributes",
 "kind": "yaml-key (entity level)",
 "detail": "The four entity-level keys shown. `id` and `name` are identical in both examples (\"CUSTOMER\"/\"CUSTOMER\", \"ORDER_LINE\"/\"ORDER_LINE\"). `definition` is prose: \"Customer who places orders\", \"Individual item within an order\"."
}
---
{
 "name": "id / definition / type / effective_timestamp",
 "kind": "yaml-key (attribute level)",
 "detail": "The four attribute-level keys shown. Every attribute in both examples sets `effective_timestamp: true` (unquoted boolean)."
}
---
{
 "name": "type: \"STRING\" / type: \"NUMBER\"",
 "kind": "type-mapping",
 "detail": "The only two attribute types appearing in the post. Uppercase, double-quoted. STRING used for names, cities, statuses and identifiers (ORDER_LINE_ID); NUMBER used for QUANTITY and LINE_AMOUNT."
}
---
{
 "name": "relationships:",
 "kind": "yaml-key",
 "detail": "Top-level YAML key, shown at the same indentation level as `entities:` (column 0) in the second block. Verbatim:\nrelationships:\n  - name: \"IS_FOR_PRODUCT\"\n    definition: \"Line item references a product\"\n    source_entity_id: \"ORDER_LINE\"\n    target_entity_id: \"PRODUCT\"\n\n  - name: \"BELONGS_TO\"\n    definition: \"Order line belongs to an order\"\n    source_entity_id: \"ORDER_LINE\"\n    target_entity_id: \"ORDER\""
}
---
{
 "name": "name / definition / source_entity_id / target_entity_id",
 "kind": "yaml-key (relationship level)",
 "detail": "The four relationship keys. Note relationships use `name` (not `id`) as their identifier, unlike entities and attributes which use `id`."
}
---
{
 "name": "IS_FOR_PRODUCT, BELONGS_TO",
 "kind": "naming-rule (relationships)",
 "detail": "Relationship names are business verb phrases in UPPER_SNAKE_CASE, read source\u2192target: \"an order line IS_FOR a product and BELONGS_TO an order\". IS_FOR_PRODUCT embeds the target noun; BELONGS_TO does not \u2014 both forms appear."
}
---
{
 "name": "CUSTOMER, ORDER, ORDER_LINE, PRODUCT",
 "kind": "naming-rule (entities)",
 "detail": "Entity ids/names are singular, UPPER_SNAKE_CASE nouns. Four entities appear across the examples."
}
---
{
 "name": "CUSTOMER_NAME, CUSTOMER_CITY, CUSTOMER_STATUS, ORDER_LINE_ID, QUANTITY, LINE_AMOUNT",
 "kind": "naming-rule (attributes)",
 "detail": "Attribute ids are UPPER_SNAKE_CASE. Descriptive attributes of an entity are prefixed with the entity name (CUSTOMER_NAME, CUSTOMER_CITY, CUSTOMER_STATUS, ORDER_LINE_ID); measures on ORDER_LINE are not prefixed (QUANTITY, LINE_AMOUNT)."
}
---
{
 "name": "daana-cli deploy",
 "kind": "cli-command",
 "detail": "First of the \"two commands\" run after entities are defined and mapped to source tables. No flags shown in the post."
}
---
{
 "name": "daana-cli execute",
 "kind": "cli-command",
 "detail": "Second of the two commands. No flags shown in the post."
}
---
{
 "name": "VIEW_CUSTOMER",
 "kind": "generated-object",
 "detail": "\"Current state. One row per customer, latest attribute values.\" One of three views generated per entity."
}
---
{
 "name": "VIEW_CUSTOMER_HIST",
 "kind": "generated-object",
 "detail": "\"Full history. Every change tracked, time-travel ready.\""
}
---
{
 "name": "VIEW_CUSTOMER_WITH_REL",
 "kind": "generated-object",
